INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('cro-morning-checkin', 'cro-relational', 'Daily Networking Check-in', 'Check reconnect priorities, scan dormant relationships, review networking opportunities', 'cron', '0 8 * * *', 'custom_prompt', '{"prompt":"Execute Daily Networking Check-in. Step 1: Query people DB for entries where last_connected_date exceeds connection_frequency. Step 2: Check relational_journal for entries in last 24 hours. Step 3: Identify people with ''Reconnect By'' ≤ today. Step 4: Scan for dormant relationships (30+ days since last contact). Step 5: Cross-reference with days DB for today''s operational context. Produce: 1) Reconnect priority list — names, last connected, relationship status, 2) Dormant relationship alerts — who hasn''t been contacted in 30+ days, 3) Networking opportunities — based on today''s context, 4) Value exchange balance check — any relationships showing ''I am in Debt''. If no action needed: reply HEARTBEAT_OK. If reconnects needed: produce brief with names and suggested approaches.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cro-weekly-review', 'cro-relational', 'Weekly Relationship Health Review', 'Weekly relationship health analysis with value exchange trends', 'cron', '0 18 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Relationship Health Review. Step 1: Query relational_journal with period=past_week to gather all interaction data. Step 2: Analyze relationship health trends — who am I nurturing, who am I neglecting. Step 3: Check value exchange balance across all active relationships. Step 4: Identify reconnect patterns — frequency vs desired trajectory. Step 5: Cross-reference with activity_log energy/mood to correlate relational capacity with emotional state. Produce: 1) Weekly interaction summary — count, types, outcomes, 2) Relationship health trends — strengthening, stable, weakening, 3) Value exchange analysis — balanced, in-credit, in-debt relationships, 4) Reconnect priorities for next week, 5) Network growth — new connections, dormant alerts. Update people profiles with weekly insights. SYSTEMIC FLAG CHECK: If relationship concentration risk detected (80%+ interactions with 1-2 people) or value exchange systematically imbalanced → send message.send to ceo-strategic with relational pattern flag. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cro-monthly-synthesis', 'cro-relational', 'Monthly Network Synthesis', 'Monthly network synthesis with growth metrics and campaign effectiveness', 'cron', '0 16 L * *', 'custom_prompt', '{"prompt":"Execute Monthly Network Synthesis. Step 1: Query relational_journal with period=past_month for comprehensive interaction data. Step 2: Analyze network growth metrics — new connections, strengthened relationships, lost connections. Step 3: Review campaigns — engagement rates, conversion rates, reach vs targets. Step 4: Identify strategic positioning opportunities — key relationships moving toward desired trajectory. Step 5: Generate monthly network health report — overall network vitality, dormant relationship count, campaign ROI. Produce: 1) Monthly network growth report, 2) Campaign effectiveness analysis, 3) Strategic relationship positioning assessment, 4) Dormant relationship alerts (60+ days), 5) Next month''s networking priorities. Save synthesis to reports DB via lifeos_create_report. SYSTEMIC FLAG CHECK: If network health declining month-over-month or critical relationships dormant 60+ days → send message.send to ceo-strategic with systemic relational pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
